CREATE TABLE public.journey_goals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, goal text NOT NULL, custom text, why text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.journey_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, goal_id uuid REFERENCES public.journey_goals(id) ON DELETE SET NULL, title text NOT NULL, period text NOT NULL DEFAULT 'monthly', starts_on date NOT NULL DEFAULT current_date, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.journey_steps (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, plan_id uuid NOT NULL REFERENCES public.journey_plans(id) ON DELETE CASCADE, period_index integer NOT NULL DEFAULT 1, title text NOT NULL, category text NOT NULL DEFAULT 'outro', package_id uuid, status text NOT NULL DEFAULT 'testing', status_history jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.journey_reflections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, plan_id uuid NOT NULL REFERENCES public.journey_plans(id) ON DELETE CASCADE, step_id uuid REFERENCES public.journey_steps(id) ON DELETE CASCADE, note text, emotional_note text, practicality integer, maintenance integer, self_esteem integer, social_reception text, include_in_report boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.journey_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, plan_id uuid NOT NULL REFERENCES public.journey_plans(id) ON DELETE CASCADE, kind text NOT NULL DEFAULT 'month', content jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.journey_goals, public.journey_plans, public.journey_steps, public.journey_reflections, public.journey_reports TO authenticated;
GRANT ALL ON public.journey_goals, public.journey_plans, public.journey_steps, public.journey_reflections, public.journey_reports TO service_role;
ALTER TABLE public.journey_goals ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.journey_plans ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.journey_steps ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.journey_reflections ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.journey_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own" ON public.journey_goals FOR ALL TO authenticated USING (auth.uid()=user_id) WITH CHECK (auth.uid()=user_id);
CREATE POLICY "own" ON public.journey_plans FOR ALL TO authenticated USING (auth.uid()=user_id) WITH CHECK (auth.uid()=user_id);
CREATE POLICY "own" ON public.journey_steps FOR ALL TO authenticated USING (auth.uid()=user_id) WITH CHECK (auth.uid()=user_id);
CREATE POLICY "own" ON public.journey_reflections FOR ALL TO authenticated USING (auth.uid()=user_id) WITH CHECK (auth.uid()=user_id);
CREATE POLICY "own" ON public.journey_reports FOR ALL TO authenticated USING (auth.uid()=user_id) WITH CHECK (auth.uid()=user_id);
ALTER TABLE public.photos ADD COLUMN journey_step_id uuid REFERENCES public.journey_steps(id) ON DELETE SET NULL, ADD COLUMN pair_role text;
ALTER TABLE public.reminders ADD COLUMN journey_plan_id uuid REFERENCES public.journey_plans(id) ON DELETE CASCADE;
CREATE INDEX ON public.journey_steps(plan_id);
CREATE INDEX ON public.journey_reflections(plan_id);
CREATE INDEX ON public.journey_reports(plan_id);